@transaction.atomic
def materialize_chore_program(
    program: ChoreProgram, *, start: Any = None
) -> list[FamilyTask]:
    # Re-fetch with row lock to prevent concurrent materialization races
    program = ChoreProgram.objects.select_for_update().get(pk=program.pk)

    if not program.is_active:
        return []

    """Web Tasks board: Overdue / Today / This Week / Recently completed."""
    payload = get_dashboard_payload(request.user, request=request)

    family_ids = get_accessible_family_ids(request.user)
    completed_cutoff = timezone.now() - timedelta(days=14)
    recently_completed = list(
        FamilyTask.objects.filter(
            family_id__in=family_ids,
            status=FamilyTask.Status.COMPLETED,
            completed_at__gte=completed_cutoff,
        )
        .select_related("assigned_to", "family")
        .order_by("-completed_at")[:20]
    )

    context = {
        "overdue_tasks": list(payload["overdue"]),
        "today_tasks": list(payload["today"]),
        "this_week_tasks": list(payload["this_week"]),
        "completed_tasks": recently_completed,
        "inbox_captures": list(payload["inbox"]),
    }
    return render(request, "organize/tasks_board.html", context)


