{% extends "base.html" %}
{% load static %}

{% block title %}Tasks{% endblock %}

{% block extra_css %}
<style>
    .tasks-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: var(--space-6);
        flex-wrap: wrap;
        gap: var(--space-4);
    }

    .tasks-section {
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        margin-bottom: var(--space-5);
        overflow: hidden;
    }

    .tasks-section-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: var(--space-4) var(--space-5);
        border-bottom: 1px solid var(--gray-200);
    }

    .tasks-section-title {
        font-size: var(--font-size-lg);
        font-weight: 600;
        margin: 0;
        display: flex;
        align-items: center;
        gap: var(--space-2);
    }

    .tasks-section-count {
        background: var(--gray-100);
        color: var(--gray-700);
        border-radius: var(--radius-full);
        padding: 2px 10px;
        font-size: var(--font-size-sm);
        font-weight: 500;
    }

    .tasks-section--overdue .tasks-section-title { color: var(--danger, #dc2626); }
    .tasks-section--overdue .tasks-section-count { background: #fee2e2; color: #991b1b; }

    .task-row {
        display: flex;
        align-items: flex-start;
        gap: var(--space-3);
        padding: var(--space-3) var(--space-5);
        border-bottom: 1px solid var(--gray-100);
        text-decoration: none;
        color: inherit;
    }
    .task-row:last-child { border-bottom: none; }
    .task-row:hover { background: var(--gray-50); }

    .task-row-icon {
        flex-shrink: 0;
        width: 32px;
        height: 32px;
        border-radius: 50%;
        background: var(--gray-100);
        display: flex;
        align-items: center;
        justify-content: center;
        color: var(--gray-600);
    }
    .task-row--completed .task-row-icon { background: #d1fae5; color: #065f46; }

    .task-row-body { flex: 1; min-width: 0; }
    .task-row-title {
        font-weight: 500;
        margin: 0;
        color: var(--gray-900);
    }
    .task-row--completed .task-row-title {
        text-decoration: line-through;
        color: var(--gray-500);
    }
    .task-row-meta {
        font-size: var(--font-size-sm);
        color: var(--gray-600);
        margin-top: 2px;
        display: flex;
        gap: var(--space-3);
        flex-wrap: wrap;
    }

    .task-empty {
        padding: var(--space-5);
        text-align: center;
        color: var(--gray-500);
        font-size: var(--font-size-sm);
    }
</style>
{% endblock %}

{% block content %}
<div class="container py-4">
    <div class="tasks-header">
        <div>
            <h1 class="mb-1">Tasks</h1>
            <p class="text-muted mb-0">Family to-dos across overdue, today, and this week.</p>
        </div>
        <div>
            <a href="{% url 'organize_task_create' %}" class="btn btn-primary" id="add-task-btn">
                <i class="bi bi-plus-lg me-1"></i>Add Task
            </a>
        </div>
    </div>

    {# Overdue #}
    <section class="tasks-section tasks-section--overdue" data-testid="tasks-section-overdue">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-exclamation-circle"></i> Overdue
            </h2>
            <span class="tasks-section-count">{{ overdue_tasks|length }}</span>
        </div>
        {% if overdue_tasks %}
            {% for task in overdue_tasks %}
                {% include "organize/_task_row.html" with task=task %}
            {% endfor %}
        {% else %}
            <div class="task-empty">Nothing overdue. Nice work.</div>
        {% endif %}
    </section>

    {# Today #}
    <section class="tasks-section" data-testid="tasks-section-today">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-sun"></i> Today
            </h2>
            <span class="tasks-section-count">{{ today_tasks|length }}</span>
        </div>
        {% if today_tasks %}
            {% for task in today_tasks %}
                {% include "organize/_task_row.html" with task=task %}
            {% endfor %}
        {% else %}
            <div class="task-empty">Nothing due today.</div>
        {% endif %}
    </section>

    {# This Week #}
    <section class="tasks-section" data-testid="tasks-section-this-week">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-calendar-week"></i> This Week
            </h2>
            <span class="tasks-section-count">{{ this_week_tasks|length }}</span>
        </div>
        {% if this_week_tasks %}
            {% for task in this_week_tasks %}
                {% include "organize/_task_row.html" with task=task %}
            {% endfor %}
        {% else %}
            <div class="task-empty">Nothing scheduled this week.</div>
        {% endif %}
    </section>

    {# Recently completed #}
    {% if completed_tasks %}
    <section class="tasks-section" data-testid="tasks-section-completed">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-check2-circle"></i> Recently Completed
            </h2>
            <span class="tasks-section-count">{{ completed_tasks|length }}</span>
        </div>
        {% for task in completed_tasks %}
            {% include "organize/_task_row.html" with task=task completed=True %}
        {% endfor %}
    </section>
    {% endif %}
</div>
{% endblock %}

