@transaction.atomic
def convert_capture_to_grocery_list(
    capture: InboxCapture,
    *,
    name: str | None = None,
    description: str = "",
    owner: User | None = None,
    items: list[str] | None = None,
) -> GroceryList:
    owner = owner or capture.created_by
    if owner is None:
        raise ValueError("Inbox capture cannot be converted without an owning user.")

    grocery_list = GroceryList.objects.create(
        family=capture.family,
        name=name
        or capture.normalized_payload.get("suggested_title")
        or "Shopping list",
        description=description or capture.raw_text or "",
        owner=owner,
        is_group=True,
    )

    item_names = (
        items
        if items is not None
        else [
            str(item_name).strip()
            for item_name in capture.normalized_payload.get("suggested_items", [])
            if str(item_name).strip()
        ]
    )
    grocery_items = [
        GroceryItem(
            grocery_list=grocery_list,
            name=item_name,
            position=position,
            created_by=owner,
        )
        for position, item_name in enumerate(item_names, start=1)
    ]
    if grocery_items:
        GroceryItem.objects.bulk_create(grocery_items)

    capture.converted_grocery_list = grocery_list
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(update_fields=["converted_grocery_list", "status", "updated_at"])
    return grocery_list


@transaction.atomic
def convert_capture_to_event(
    capture: InboxCapture,
    event_payload: dict[str, Any],
    *,
    source_client_app: str = ClientApp.ORGANIZE,
) -> Event:
    """Materialize an Event from an InboxCapture proposal.

    Used for clean .ics auto-conversion and for user-confirmed event
    proposals from the review queue. Sets ``external_source='inbox_email'``
    plus the ICS UID as ``external_id`` so future updates to the same UID
    can ``update_or_create`` against this row instead of duplicating.
    """

    title = (event_payload.get("summary") or event_payload.get("title") or "").strip()
    if not title:
        raise ValueError("Event conversion requires a title or summary.")

    starts_at_raw = event_payload.get("starts_at") or event_payload.get("start_time")
    ends_at_raw = event_payload.get("ends_at") or event_payload.get("end_time")
    if not starts_at_raw:
        raise ValueError("Event conversion requires starts_at / start_time.")

    def _parse_dt(value: Any) -> dt_datetime:
        if isinstance(value, dt_datetime):
            dt_value = value
        else:
            dt_value = dt_datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if timezone.is_naive(dt_value):
            dt_value = timezone.make_aware(dt_value, dt_timezone.utc)
        return dt_value

    start_time = _parse_dt(starts_at_raw)
    end_time = (
        _parse_dt(ends_at_raw) if ends_at_raw else start_time + timedelta(hours=1)
    )

    creator = capture.created_by
    if creator is None:
        membership = (
            FamilyMembership.objects.filter(family=capture.family, is_active=True)
            .order_by("-is_admin", "joined_at")
            .first()
        )
        if membership is None:
            raise ValueError(
                "Cannot convert capture to event: no active member on family."
            )
        creator = membership.user

    uid = (event_payload.get("uid") or "").strip()
    # Namespace external_id by family so an ICS UID from one family cannot
    # match (and overwrite) another family's existing inbox_email event.
    namespaced_uid = uid or f"capture:{capture.pk}"
    external_id = f"{capture.family.pk}:{namespaced_uid}"

    # No DB-level unique constraint on (external_source, external_id) in the
    # Event table today, so we filter-then-write under the surrounding
    # @transaction.atomic, scoped to the family, to avoid MultipleObjectsReturned
    # and to prevent cross-tenant lookups.
    event = (
        Event.secure.for_family(capture.family, include_meta=False)
        .select_for_update()
        .filter(
            external_source="inbox_email",
            external_id=external_id,
        )
        .first()
    )
    created = event is None
    event_fields = {
        "title": title,
        "description": (event_payload.get("description") or "")[:5000],
        "location": (event_payload.get("location") or "")[:255],
        "start_time": start_time,
        "end_time": end_time,
        "family_group": capture.family,
        "creator": creator,
        "is_external": True,
        "external_source": "inbox_email",
        "external_id": external_id,
    }
    if event is None:
        event = Event.secure.create(**event_fields)
    else:
        for field, value in event_fields.items():
            setattr(event, field, value)
        event.save()
    event = cast(Event, event)

    capture.converted_event = event
    capture.status = InboxCapture.Status.CONVERTED
    capture.source_client_app = canonicalize_client_app(
        capture.source_client_app, default=""
    ) or canonicalize_client_app(source_client_app, default=ClientApp.ORGANIZE)
    capture.save(
        update_fields=[
            "converted_event",
            "status",
            "source_client_app",
            "updated_at",
        ]
    )
    logger.info(
        "organize.convert_capture_to_event",
        extra={
            "capture": str(capture.pk),
            "event": str(event.pk),
            "created_new_event": created,
            "uid": uid,
        },
    )
    return event


@transaction.atomic
def create_tasks_from_capture(
    capture: InboxCapture,
    *,
    reviewed_tasks: list[dict[str, Any]],
) -> list[FamilyTask]:
    capture = InboxCapture.objects.select_for_update().get(pk=capture.pk)
    normalized_payload = dict(capture.normalized_payload or {})
    existing_task_ids = [
        str(task_id)
        for task_id in normalized_payload.get("created_task_ids", [])
        if isinstance(task_id, str)
    ]
    if capture.status == InboxCapture.Status.CONVERTED:
        existing_task_map = {
            str(task.id): task
            for task in FamilyTask.objects.filter(id__in=existing_task_ids)
        }
        existing_tasks = [
            existing_task_map[task_id]
            for task_id in existing_task_ids
            if task_id in existing_task_map
        ]
        if not existing_tasks and capture.converted_task_id:
            existing_tasks = [capture.converted_task] if capture.converted_task else []
        if existing_tasks:
            return existing_tasks
        raise TaskCaptureCreateError(
            "Tasks have already been created from this capture."
        )

    if normalized_payload.get("kind") == "medication_task_bundle":
        reviewed_medication_tasks = _merge_reviewed_medication_drafts(
            normalized_payload,
            reviewed_tasks,
        )
        selected_tasks = [
            task
            for task in reviewed_medication_tasks
            if task.get("selected", True) and str(task.get("title", "")).strip()
        ]
        if not selected_tasks:
            raise TaskCaptureCreateError("Select at least one task to create.")
        created_series, created_tasks = materialize_medication_task_bundle(
            family=capture.family,
            created_by=capture.created_by,
            bundle=normalized_payload,
            reviewed_tasks=reviewed_medication_tasks,
            source_client_app=capture.source_client_app or ClientApp.ORGANIZE,
            source_object=capture,
            default_reminder_recipient=capture.created_by,
