def _proposal_index_from_post(request: Any) -> int:
    try:
        return max(0, int(request.POST.get("proposal_index", "0")))
    except (TypeError, ValueError):
        return 0


def _items_from_post(request: Any) -> list[str] | None:
    items = [item.strip() for item in request.POST.getlist("items") if item.strip()]
    if items:
        return items
    items_text = request.POST.get("items_text", "")
    if not items_text.strip():
        return None
    return [line.strip() for line in items_text.splitlines() if line.strip()]


def _medication_tasks_from_post(
    request: Any, capture: InboxCapture
) -> list[dict[str, Any]]:
    payload = capture.normalized_payload or {}
    raw_drafts = payload.get("task_drafts")
    if not isinstance(raw_drafts, list):
        return []

    has_explicit_task_fields = "medication_task_count" in request.POST
    try:
        count = int(request.POST.get("medication_task_count", len(raw_drafts)))
    except (TypeError, ValueError):
        count = len(raw_drafts)

    reviewed_tasks: list[dict[str, Any]] = []
    for index, raw_draft in enumerate(raw_drafts[: max(0, count)]):
        if not isinstance(raw_draft, dict):
            continue
        prefix = f"medication_tasks-{index}"
        draft = dict(raw_draft)
        draft["selected"] = (
            request.POST.get(f"{prefix}-selected") == "on"
            if has_explicit_task_fields
            else draft.get("selected", True)
        )
        for field in (
            "title",
            "notes",
            "due_window_start_at",
            "due_at",
            "due_window_end_at",
        ):
            value = request.POST.get(f"{prefix}-{field}")
            if value is not None:
                draft[field] = value.strip()
        draft["reminders_enabled"] = (
            request.POST.get(f"{prefix}-reminders_enabled") == "on"
        )
        reviewed_tasks.append(draft)
    return reviewed_tasks


