            </h2>
            <span class="tasks-section-count">{{ overdue_tasks|length }}</span>
        </div>
        {% if overdue_tasks %}
            {% for task in overdue_tasks %}
                {% include "organize/_task_row.html" with task=task %}
            {% endfor %}
        {% else %}
            <div class="task-empty">Nothing overdue. Nice work.</div>
        {% endif %}
    </section>

    {# Today #}
    <section class="tasks-section" data-testid="tasks-section-today">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-sun"></i> Today
            </h2>
            <span class="tasks-section-count">{{ today_tasks|length }}</span>
        </div>
        {% if today_tasks %}
            {% for task in today_tasks %}
                {% include "organize/_task_row.html" with task=task %}
            {% endfor %}
        {% else %}
            <div class="task-empty">Nothing due today.</div>
        {% endif %}
    </section>

    {# This Week #}
    <section class="tasks-section" data-testid="tasks-section-this-week">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-calendar-week"></i> This Week
            </h2>
            <span class="tasks-section-count">{{ this_week_tasks|length }}</span>
        </div>
        {% if this_week_tasks %}
            {% for task in this_week_tasks %}
                {% include "organize/_task_row.html" with task=task %}
            {% endfor %}
        {% else %}
            <div class="task-empty">Nothing scheduled this week.</div>
        {% endif %}
    </section>

    {# Recently completed #}
    {% if completed_tasks %}
    <section class="tasks-section" data-testid="tasks-section-completed">
        <div class="tasks-section-header">
            <h2 class="tasks-section-title">
                <i class="bi bi-check2-circle"></i> Recently Completed
            </h2>
            <span class="tasks-section-count">{{ completed_tasks|length }}</span>
        </div>
        {% for task in completed_tasks %}
            {% include "organize/_task_row.html" with task=task completed=True %}
        {% endfor %}
    </section>
    {% endif %}
</div>
{% endblock %}

